import { ApiProperty, ApiPropertyOptional } from '@nestjs/swagger';
import { IsOptional, IsString } from 'class-validator';

export class LinkGoogleCalendarDto {
  @ApiProperty({
    description:
      'Authorization code generated by Google OAuth 2.0 with calendar scopes and offline access.',
    example: '4/0AQSTgQH...',
  })
  @IsString()
  authorizationCode!: string;

  @ApiPropertyOptional({
    description:
      'Redirect URI used in the OAuth flow. If omitted, backend uses GOOGLE_OAUTH_REDIRECT_URI.',
    example: 'http://localhost:4200/auth/google/callback',
  })
  @IsOptional()
  @IsString()
  redirectUri?: string;
}
